import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  resultCodeOrdersActionResultCodeSchema,
  type ResultCodeOrdersActionResultCode,
} from "./result-code-orders-action-result-code.js";
import { typeOrdersActionTypeSchema, type TypeOrdersActionType } from "./type-orders-action-type.js";

export type Action43 = {
  /** A unique identifier generated by the platform to identify an action. */
  id?: string;
  /** Indicates the specific action taken. */
  type?: TypeOrdersActionType;
  /** GP API specific created time indicating when the instance of the resource was created. */
  timeCreated?: string;
  /** The result of the action executed. */
  resultCode?: ResultCodeOrdersActionResultCode;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const action43Schema: Schema<Action43> = s.object<Action43>(
  {
    id: s.optional(s.string()),
    type: s.optional(s.lazy(() => typeOrdersActionTypeSchema)),
    timeCreated: s.optional(s.string()),
    resultCode: s.optional(s.lazy(() => resultCodeOrdersActionResultCodeSchema)),
    appId: s.optional(s.string()),
    appName: s.optional(s.string()),
    _keysMap: {
      timeCreated: "time_created",
      resultCode: "result_code",
      appId: "app_id",
      appName: "app_name",
    },
  },
  { additionalProperties: s.json() },
);
